begin;select no_plan();
select has_function('public','provider_diagnostic',array['uuid','text','text','jsonb'],'isolated diagnostic dispatcher exists');
select ok(has_function_privilege('service_role','public.provider_diagnostic(uuid,text,text,jsonb)','execute') and not has_function_privilege('anon','public.provider_diagnostic(uuid,text,text,jsonb)','execute') and not has_function_privilege('authenticated','public.provider_diagnostic(uuid,text,text,jsonb)','execute'),'only existing service role may dispatch');
select ok(not has_table_privilege('service_role','private.provider_diagnostic_campaigns','insert') and not has_table_privilege('authenticated','private.provider_diagnostic_attempts','select'),'campaign arming and evidence are not browser or service table APIs');
select is((select count(*) from private.provider_diagnostic_campaigns),0::bigint,'migration seeds no paid authorization');
create temporary table diagnostic_money_before as select jsonb_build_object('wallets',(select coalesce(jsonb_agg(to_jsonb(t)),'[]')from private.credit_wallets t),'operations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]')from private.credit_operations t),'settings',(select jsonb_agg(to_jsonb(t))from private.chat_usage_settings t)) snapshot;
select throws_ok($$select public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','claim')$$,'P0001','diagnostic_not_approved','empty campaign never authorizes supplier traffic');
insert into private.provider_diagnostic_campaigns(id,approval_ref,approved_at,expires_at)values('11111111-1111-4111-8111-111111111111','synthetic offline approval',now(),now()+interval '10 minutes');
select throws_ok($$select public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','claim')$$,'P0001','diagnostic_not_approved','a created campaign is disabled by default');
update private.provider_diagnostic_campaigns set state='armed';
select throws_ok($$select public.provider_diagnostic('11111111-1111-4111-8111-111111111111','other','claim')$$,'P0001','invalid_diagnostic_request','only two fixed slots exist');
select throws_ok($$select public.provider_diagnostic('11111111-1111-4111-8111-111111111111','sol','claim')$$,'P0001','diagnostic_not_ready','second model waits for trustworthy first receipt');
create temporary table diagnostic_claim as select public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','claim') c;
select is(c->>'action','start','one durable first supplier claim')from diagnostic_claim;
select is(c->>'maxInputTokens','2048','diagnostic input budget is independent of tariffs')from diagnostic_claim;
select is(c->>'maxOutputTokens','128','diagnostic output cap is independent of tariffs')from diagnostic_claim;
select is(c->>'model','gpt-6-astra','fixed first model')from diagnostic_claim;
select is(public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','claim')->>'attemptState','claimed','lost acknowledgement cannot authorize another attempt');
create temporary table diagnostic_receipt as select '{"outcome":"verified","receipt":{"providerRequestId":"chatcmpl-synthetic","resolvedModel":"gpt-6-astra","serviceTier":"default","requestedCacheTtl":"30m","inputTokens":12,"outputTokens":2,"totalTokens":14,"cachedInputTokens":0,"cacheWriteTokens":0,"finishReason":"stop"}}'::jsonb r;
select is(public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','record',r)->>'attemptState','verified','verified first result persisted')from diagnostic_receipt;
select is(public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','status')->>'estimatedUsdMicros','220','directory cost calculated without user charges');
select is(public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','record',r)->>'attemptState','verified','same terminal receipt is idempotent')from diagnostic_receipt;
select throws_ok($$select public.provider_diagnostic('11111111-1111-4111-8111-111111111111','astra','record','{"outcome":"uncertain","reason":"provider_evidence_unverified"}')$$,'P0001','diagnostic_terminal_conflict','terminal verified evidence cannot be rewritten');
select is(public.provider_diagnostic('11111111-1111-4111-8111-111111111111','sol','claim')->>'model','gpt-6.1-sol','only second fixed model is then permitted');
select is(public.provider_diagnostic('11111111-1111-4111-8111-111111111111','sol','record',jsonb_set(r,'{receipt,resolvedModel}','"gpt-6.1-sol"'))->>'state','complete','both successful diagnostics complete the bounded campaign')from diagnostic_receipt;
select is((select count(*)from private.provider_diagnostic_attempts),2::bigint,'at most two provider attempts exist');
select is(public.provider_diagnostic('11111111-1111-4111-8111-111111111111','sol','claim')->>'attemptState','verified','completed attempt never starts again');

insert into private.provider_diagnostic_campaigns(id,approval_ref,approved_at,expires_at,state)values('22222222-2222-4222-8222-222222222222','synthetic uncertain approval',now(),now()+interval '10 minutes','armed');
select public.provider_diagnostic('22222222-2222-4222-8222-222222222222','astra','claim');
select is(public.provider_diagnostic('22222222-2222-4222-8222-222222222222','astra','record',jsonb_set(r,'{receipt,outputTokens}','129'))->>'attemptState','needs_review','overbudget receipt halts without cost fabrication')from diagnostic_receipt;
select throws_ok($$select public.provider_diagnostic('22222222-2222-4222-8222-222222222222','sol','claim')$$,'P0001','diagnostic_not_approved','uncertainty prevents the second paid request');
select is(public.provider_diagnostic('22222222-2222-4222-8222-222222222222','astra','claim')->>'attemptState','needs_review','unknown result remains spent');

insert into private.provider_diagnostic_campaigns(id,approval_ref,approved_at,expires_at,state)values('33333333-3333-4333-8333-333333333333','synthetic expired approval',now()-interval '20 minutes',now()-interval '10 minutes','armed');
select throws_ok($$select public.provider_diagnostic('33333333-3333-4333-8333-333333333333','astra','claim')$$,'P0001','diagnostic_not_approved','expired authorization never starts');
select throws_ok($$insert into private.provider_diagnostic_campaigns(id,approval_ref,approved_at,expires_at)values(gen_random_uuid(),'synthetic long authorization',now(),now()+interval '16 minutes')$$,'23514',null,'arming window cannot exceed fifteen minutes');
select is((select jsonb_build_object('wallets',(select coalesce(jsonb_agg(to_jsonb(t)),'[]')from private.credit_wallets t),'operations',(select coalesce(jsonb_agg(to_jsonb(t)),'[]')from private.credit_operations t),'settings',(select jsonb_agg(to_jsonb(t))from private.chat_usage_settings t))),snapshot,'diagnostics never alter wallet operations or formal tariffs')from diagnostic_money_before;
select finish();rollback;
